  getByNidnJadwal(nidn: string | number, query?: {
    /** Periode (default aktif) Contoh: `20261` */
    tahun_id?: string;
    /** Nomor halaman, mulai 1. */
    page?: number;
    /** Jumlah data per halaman (maksimal 100). */
    per_page?: number;
  } & Query, options?: RequestOptions): Promise<ApiResult<Array<S.Jadwal>>> {
    return this.client.request({ method: 'GET', path: '/v1/dosen/{nidn}/jadwal', query: { ...query, nidn } }, options);
  }

